def _is_historical(rel: str) -> bool:
    """该仓库根相对路径是否属"历史记录文件"（不参与引用/节名/历史来源检查）。"""
    return rel in HISTORICAL_FILES


def check_maven_mirror_guard():
    """Maven「仓库与镜像」节防线：指定仓库与两条前提条件不得被删改。

    用户口径：落点只有这一个——不管什么系统、什么环境，都是用户家目录下的那一处。
    故本防线不核"平台缓存目录怎么取"，而是核**"只有这一个落点"**：既须由用户家目录
    算出这个路径，也不得再出现"随平台另取一套缓存目录"与项目内临时目录这类第二落点、
    以及换落点的入口；家目录取不到时须报错退出、不得静默换地方。

"""
    phase("Maven 仓库与镜像防线检查")
    rel = "specs/stack/maven.adoc"
    path = os.path.join(REPO_ROOT, *rel.split("/"))
    if not os.path.isfile(path):
        err(f"{rel} 缺失（Maven 栈规范的唯一落点）", rel)
        phase_done()
        return
    text = open(path, encoding="utf-8").read()
    section = _section_text(text, "仓库与镜像") or ""
    if not section:
        err("maven.adoc 缺少「仓库与镜像」节", rel)
        phase_done()
        return

    required = [
        ("外网出口 IP 在中国大陆才触发", "外网出口 IP 在中国大陆"),
        ("指定的中央仓库地址", "mirrors.cloud.tencent.com/nexus/repository/maven-public/"),
        ("优先用该仓库（不得自行另挑）", "必须先用这个仓库"),
        ("不可用才可换源（降级触发条件）", "仅当它不可用"),
        ("换源也须在境内（其余不得放宽）", "其他在境内的镜像站"),
        ("已配置过即不做（不覆盖既有配置）", "已配置过即不做"),
        ("未配置过才做（前提条件）", "未配置过 Maven 仓库/镜像"),
    ]
    for name, token in required:
        if token not in section:
            err(f"「仓库与镜像」节缺少要点：{name}（应含 `{token}`）", rel)
    phase_done()


# ---- 代码质量 / 生成效率与 token 纪律 / 改动后复核 三道防线 ----
# 三条依据来源（用户提出）：
#   ①「有的时候功能是写出来了，但是代码质量比较低」→ 新产出即高质的整体下限此前没有成文判据；
#   ②「提高生成效率的规范」→ 此前只有「执行吞吐」管调用形态，不管「这件事该做几轮」；
#   ③「不影响功能完整性和代码质量的前提下提高 token 利用率……是一回事吗」
#      → 此前没有 token 维度的判据，也没把「利用率 / 节省」的区分与「不得越过质量」写清。
# 三条共同的前提是**不能影响效率和效果**，故每道防线都同时钉住「边界条」（效率/节省不得
# 越过质量、完整性、验证）——只钉「要不要求」而不钉边界，等于给出一条可被读成「为省而省」的规则。
QUALITY_SECTION = "代码质量（新产出即高质）"
QUALITY_SPEC = "specs/general/coding.adoc"
GEN_EFF_SECTION = "生成效率（同等质量下最少往返）"
TOKEN_SECTION = "token 纪律（提高利用率与节省开销）"
CONTEXT_SPEC = "specs/general/context.adoc"
AFTER_REVIEW_SECTION = "改完规范必做的五件事（机械手段必跑，干净子 agent 复核不可漏）"
CHANGE_REVIEW_SECTION = "改动后的 review（每次改完都得复核一次）"
VERIFY_SPEC = "specs/general/verify.adoc"
REVIEW_SPEC = "specs/general/review.adoc"
QUALITY_LIBRARY = "library/quality.adoc"

