def check_rename_split_guard():
    """『重命名与内容修改须分两个提交防线』：用户提出的 P7 要求不得被删或降级。

"""
    phase("重命名与内容修改须分两个提交防线检查")
    rel_git = "specs/general/git.adoc"
    path = os.path.join(REPO_ROOT, *rel_git.split("/"))
    if not os.path.isfile(path):
        err(f"缺少 {rel_git}——『重命名与内容修改须分两个提交』失去权威定义落点", rel_git)
        phase_done()
        return
    with open(path, encoding="utf-8") as fh:
        text = fh.read()
    m = re.search(r"^== 重命名与内容修改须分两个提交.*?(?=\n== |\Z)", text, re.M | re.S)
    if m is None:
        err(f"{rel_git} 未找到「重命名与内容修改须分两个提交」一节——"
            "用户提出的 P7 要求失去权威定义落点（最高关注项不得被删除或降级）", rel_git)
        phase_done()
        return
    section = m.group(0)
    # 结构核对：本节的**每一项**（小标题）都须在——只删小标题而正文被并入别处、
    # 或整条 bullet 被摘掉，都会让该项在读者侧消失，而上面按"内容关键词"的核对
    # 可能被相邻条款的字样兜住（本防线必须对"整条被摘掉"这一最危险形态发声）。
    for item in RENAME_SPLIT_ITEM_LABELS:
        if item not in section:
            err(f"重命名与内容修改防线被破坏：{rel_git} 的「重命名与内容修改须分两个提交」"
                f"缺失条目『{item}』——条目的轴标题被整条摘掉/改写即等于该要求失效"
                "（本条的每一项都是用户提出要求的一部分，不得删除、不得降级为建议）", rel_git)
    # 条目内核对：只留轴标题、正文被抽空（或要求被搬进相邻条目）时，
    # 按"整节关键词"的核对会被相邻条款的字样兜住——故逐条取其**自身**的 bullet 文本再核。
    for keys, desc in RENAME_SPLIT_ITEM_KEYS:
        prefix, anchors = keys[0], keys[1:]
        item_text = _bullet_text(section, prefix[0])
        if item_text is None:
            continue  # 轴标题已由上面的条目核对报错，不重复发声
        missing = [k for k in anchors if k not in item_text]
        if missing:
            err(f"重命名与内容修改防线被破坏：{rel_git} 的『{keys[0]}』**正文**缺失 {missing}"
                f"——{desc}；该条被抽空或要求被搬进相邻条目即等于这条要求失效"
                "（本条的每一项都是用户提出要求的一部分，不得删除、不得降级为建议）", rel_git)
    for keys, desc in RENAME_SPLIT_GUARD_KEYS:
        missing = [k for k in keys if k not in section]
        if missing:
            err(f"重命名与内容修改防线被破坏：{rel_git} 的「重命名与内容修改须分两个提交」"
                f"缺失要点 {missing}——{desc}；本条是用户明确提出的最高关注项 P7，"
                "不得删除、不得降级为建议", rel_git)
    # 必加载层重申行
    rel_exec = "specs/core/execution.adoc"
    exec_path = os.path.join(REPO_ROOT, *rel_exec.split("/"))
    if not os.path.isfile(exec_path):
        err(f"缺少 {rel_exec}——P7 的必加载层重申失去落点", rel_exec)
    else:
        with open(exec_path, encoding="utf-8") as fh:
            exec_text = fh.read()
        for keys, desc in ((("重命名与内容修改须分两个提交（L1 最高关注项 P7）",),
                            "必加载层须有 P7 的重申行（该层每次会话无条件加载）"),
                           (("只做重命名、内容逐字节不变",),
                            "重申行须保留判定形态（只做重命名、内容逐字节不变）")):
            missing = [k for k in keys if k not in exec_text]
            if missing:
                err(f"重命名与内容修改防线被破坏：{rel_exec} 缺失 {missing}——{desc}",
                    rel_exec)
    # 公共入口的铁律登记
    common_path = os.path.join(REPO_ROOT, "AGENTS_COMMON.adoc")
    if os.path.isfile(common_path):
        with open(common_path, encoding="utf-8") as fh:
            common = fh.read()
        iron = common.split("== 最高优先级铁律（先读）", 1)[-1].split("\n== ", 1)[0]
        for keys, desc in ((("同一文件的重命名与内容修改必须分两个提交", "最高关注项 P7"),
                            "「最高优先级铁律」须登记 P7（进门必读，缺则下次会话读不到）"),
                           (("内容逐字节不变", "再改内容"),
                            "铁律行须保留两提交与各自只做一件事的判据形态"),
                           (("重命名与内容修改须分两个提交（默认固定动作）",),
                            "铁律行须指向权威定义节名（否则读者只知道要拆两个提交、"
                            "不知道判据与自检命令在哪）")):
            missing = [k for k in keys if k not in iron]
            if missing:
                err(f"重命名与内容修改防线被破坏：AGENTS_COMMON.adoc 的「最高优先级铁律」"
                    f"缺失 {missing}——{desc}", "AGENTS_COMMON.adoc")
    else:
        err("缺少 AGENTS_COMMON.adoc——P7 的进门必读登记无从核对", "AGENTS_COMMON.adoc")
    # 维护方不可降级清单
    rel_priority = "specs-project-maintainer/priority.adoc"
    pri_path = os.path.join(REPO_ROOT, *rel_priority.split("/"))
    if os.path.isfile(pri_path):
        with open(pri_path, encoding="utf-8") as fh:
            pri = fh.read()
        pm = re.search(r"^=== P7\..*?(?=\n=== |\Z)", pri, re.M | re.S)
        if pm is None:
            err(f"{rel_priority} 未找到最高关注项 P7 条目——不可降级清单被少列一项", rel_priority)
        else:
            seg = pm.group(0)
            for keys, desc in ((("要求（L1，最高",), "P7 须标明级别 L1、最高"),
                               (("**依据**",), "缺失『**依据**』行——依据可压缩为标准名/编号，"
                                "但不得整段删除"),
                               (("判定标准",), "P7 须有可逐条核对的判定标准"),
                               # 本轮实测：这一条曾被压成"第一个只做重命名、第二个再改内容"
                               # 两句骨架——**可核对的判据全被抽掉**（批量改名收在同一个
                               # 提交、不按文件个数分摊、未点名时只压临时中间提交且本条
                               # 原样保留），而"要求/依据/判定标准"三个轴名都还在，防线全绿。
                               # 故这里钉的是**判据本身**，不是轴名。
                               (("不按文件个数分摊",), "P7 的『要求』须写明批量改名收在同一个"
                                "改名提交里、不按文件个数分摊——缺则多文件改名会被读成"
                                "『每个文件各开一个改名提交』"),
                               (("未点名本条", "原样保留"), "P7 的『要求』须写明与「压缩提交」"
                                "的接口：未点名本条时只压临时中间提交、本条的两个提交原样保留"
                                "——缺则『用户说要合并 → 本条失效』的读法重新可用")):
                missing = [k for k in keys if k not in seg]
                if missing:
                    err(f"重命名与内容修改防线被破坏：{rel_priority} 的 P7 缺失 {missing}"
                        f"——{desc}", rel_priority)
        # 概览行须把"条款本身 L1"的那几项**完整列名**：清单是 P1-P7 七项，L1 项为
        # P1/P2/P3/P5/P6/P7（P4 条款本身是 L2）。只找 "P7" 字样不够——本轮实测：
        # 旧概览写成 "P1/P2/P3/P5/P7"，把 P6（协作执行者选择）漏在"规范性铁律"之外，
        # 连"P7 是否在概览里"这一问都能靠旧字符串答上（判据被相邻字样兜住）。
        # 故按**逐项点名**核对 L1 项的完整性（P4 另行说明其条款本身为 L2）。
        if not re.search(r"P1/P2/P3/P5/P6/P7", pri) and "P1-P7" not in pri:
            err(f"重命名与内容修改防线被破坏：{rel_priority} 的分级概览行未把条款本身为 L1 的"
                "最高关注项列全（P1/P2/P3/P5/P6/P7，P4 条款本身为 L2）——清单被加了一项而"
                "概览未同步时，读者按概览核对会漏项（本轮实测：概览漏掉 P6）", rel_priority)
    else:
        err(f"缺少 {rel_priority}——P7 的不可降级登记无从核对", rel_priority)
    # 平台层「压缩提交」与 P7 的接口（缺则"压缩提交 -> 本条失效"可在平台侧自圆其说）
    rel_cnb = "specs/platform/cnb.adoc"
    cnb_path = os.path.join(REPO_ROOT, *rel_cnb.split("/"))
    if os.path.isfile(cnb_path):
        with open(cnb_path, encoding="utf-8") as fh:
            cnb = fh.read()
        cm = re.search(r"^== 压缩提交.*?(?=\n== |\Z)", cnb, re.M | re.S)
        if cm is None:
            err(f"{rel_cnb} 未找到「压缩提交」一节——与 P7 的接口失去落点", rel_cnb)
        else:
            cseg = cm.group(0)
            # 按**接口条自身**的 bullet 核对：整节关键词核对会被相邻条款/诱饵条目兜住
            # （实测：把接口条换成"两个提交、别名、原样保留、例外与声明、点名都见别处"
            #  这类只保留通用词的诱饵，整节核对全部通过而要求已消失）。
            iface = _bullet_text(cseg, "压缩对象不含")
            if iface is None:
                err(f"{rel_cnb} 的「压缩提交」缺少与 P7 的接口条目（『压缩对象不含改名提交 + 内容修改提交』）"
                    "——平台侧可自行把『要压缩』读成『压回一个』", rel_cnb)
            else:
                for keys, desc in ((("别名", "不是"), "接口条须写明那两个提交**不是**本节的临时中间提交（否则『要压缩』即被读成『压回一个』）"),
                                   (("原样保留",), "接口条须写明未点名本条时那两个提交**原样保留**"),
                                   (("例外", "点名"), "接口条须写明与 git 规范『例外』对齐（声明须点名重命名与内容修改）")):
                    missing = [k for k in keys if k not in iface]
                    if missing:
                        err(f"重命名与内容修改防线被破坏：{rel_cnb} 的「压缩提交」与 P7 的接口缺失 {missing}"
                            f"——{desc}（该接口条的**正文**须自带这些要点，被抽空或搬到别处即等于失效）", rel_cnb)
    else:
        err(f"缺少 {rel_cnb}——P7 与「压缩提交」的接口无从核对", rel_cnb)
    phase_done()


def check_criteria_not_axis_guard():
    """『防线的核对对象是判据本体、不是轴名』防线：本轮实测教训不得只活在代码注释里。


    实证失效（本轮）：维护方最高关注项 P7 的『要求』被压成两句骨架——"要求/依据/
    判定标准"三个轴名都还在、防线全绿，而**可核对的判据**（批量改名收在同一个提交、
    不按文件个数分摊、未点名本条时只压临时中间提交且本条两提交原样保留）被整段抽掉。
    教训当时只写在 `check_specs.py` / `check_specs_test.py` 的注释里，**没有进规范正文**
    ——下一个维护者读规范时看不到，只能靠翻脚本注释（这正是本轮所修问题的同构复发：
    判据存在但不可见）。故本条把"通则进规范正文"变成机械可核对的。
    """
    phase("判据本体而非轴名防线检查")
    rel_pri = "specs-project-maintainer/priority.adoc"
    pri_path = os.path.join(REPO_ROOT, *rel_pri.split("/"))
    if not os.path.isfile(pri_path):
        err(f"缺少 {rel_pri}——『机械防线的核对对象是判据本体、不是轴名』通则失去落点",
            rel_pri)
        phase_done()
        return
    with open(pri_path, encoding="utf-8") as fh:
        pri = fh.read()
    if CRITERIA_NOT_AXIS_SECTION not in pri:
        err(f"{rel_pri} 未找到「{CRITERIA_NOT_AXIS_SECTION}」一节——该教训只剩在 "
            "script/check_specs.py 的注释里，规范正文侧看不到，下一个维护者读规范时"
            "不会知道『轴名齐全不等于判据在』（判据存在但不可见＝同构复发）", rel_pri)
        phase_done()
        return
    m = re.search(r"^=== " + re.escape(CRITERIA_NOT_AXIS_SECTION) + r".*?(?=\n=== |\n== |\Z)",
                  pri, re.M | re.S)
    if m is None:
        err(f"{rel_pri} 的「{CRITERIA_NOT_AXIS_SECTION}」小节结构被改写"
            "（小标题形态变更会导致要点核对失效）", rel_pri)
        phase_done()
        return
    section = m.group(0)
    for keys, desc in CRITERIA_NOT_AXIS_KEYS:
        missing = [k for k in keys if k not in section]
        if missing:
            err(f"『判据本体而非轴名』防线被破坏：{rel_pri} 的"
                f"「{CRITERIA_NOT_AXIS_SECTION}」缺失 {missing}——{desc}"
                "（本轮实测教训：轴名齐全、判据被抽走时防线全绿；该通则不得被删、"
                "不得降级、不得只留在脚本注释里）", rel_pri)
    # 该通则须在**维护方自己的落点**可读到（这份文件由 AGENTS.adoc 登记、维护时加载）
    if not os.path.isfile(PROJECT_FILE):
        err("缺少 AGENTS.adoc——维护方层的登记入口丢失，通则的加载面无从核对",
            "AGENTS.adoc")
    else:
        with open(PROJECT_FILE, encoding="utf-8") as fh:
            own = fh.read()
        if rel_pri not in own:
            err(f"{rel_pri} 未在维护方项目规范入口 AGENTS.adoc 登记"
                "（不会被加载、通则实际失效）", "AGENTS.adoc")
    phase_done()


def check_runtime_env_guard():
    """『运行环境须与项目声明一致』防线：用户提出的硬性要求不得被删或降级。

"""
    phase("运行环境须与项目声明一致防线检查")
    rel_ci = "specs/general/ci-cd.adoc"
    path = os.path.join(REPO_ROOT, *rel_ci.split("/"))
    if not os.path.isfile(path):
        err(f"缺少 {rel_ci}——『运行环境须与项目声明一致』失去权威定义落点", rel_ci)
        phase_done()
        return
    with open(path, encoding="utf-8") as fh:
        text = fh.read()
    m = re.search(r"^== " + re.escape(RUNTIME_ENV_SECTION) + r".*?(?=\n== |\Z)",
                  text, re.M | re.S)
    if m is None:
        err(f"{rel_ci} 未找到「{RUNTIME_ENV_SECTION}」一节——用户提出的"
            "『严格使用项目声明的那一个运行环境、严禁用别的版本』失去落点"
            "（不得删除、不得降级为建议）", rel_ci)
        phase_done()
        return
    section = m.group(0)
    for keys, desc in (
        (("（L1）", "严禁"), "条文须标注 L1 并保留『严禁/不得』的强制用语"),
        (("也能正常跑通流程，也不得换", "能跑通"),
         "须写明『即使换个版本也能跑通也不得换』——缺这句则本条最易被「能跑通」合理化掉"),
        (("判定标准", "与项目声明**不一致**", "任一命中即违规"),
         "判定标准须可逐条核对（执行所用版本与项目声明不一致即违规 + 任一命中即不合规）"
         "——只留一句口号则无法判定是否被遵守"),
        (("声明落点", "不得**为满足本条另建一份版本声明"),
         "声明落点须写明取项目**已有声明**、不得另立第二真源（多一份必然漂移，"
         "且会出现两个互相冲突的版本来源）"),
        (("降级路径", "未声明", "未确证", "不得记为通过"),
         "须写明降级路径（未声明先确认 / 声明环境不可得时如实说明并把结论标未确证、"
         "不得记为通过 / 临时诊断结论须回声明环境复核）——缺则本条会把引用方卡死在"
         "装不出声明环境的场景上，或让「用别的版本跑绿」被记成通过"),
        (("依据", "ISO/IEC/IEEE 29148", "The Twelve-Factor App"),
         "依据行须在（依据可压成标准名/编号，但不得整段删除）"),
    ):
        missing = [k for k in keys if k not in section]
        if missing:
            err(f"运行环境防线被破坏：{rel_ci} 的「{RUNTIME_ENV_SECTION}」缺失要点 {missing}"
                f"——{desc}；本条是用户明确提出的硬性要求（L1），不得删除、不得降级", rel_ci)

    # 三处引用：必加载层、验证、基线
    rel_exec = "specs/core/execution.adoc"
    exec_path = os.path.join(REPO_ROOT, *rel_exec.split("/"))
    if os.path.isfile(exec_path):
        with open(exec_path, encoding="utf-8") as fh:
            exec_text = fh.read()
        for keys, desc in ((("运行环境", "项目声明", "不得换"), rel_ci),
                           ((RUNTIME_ENV_SECTION,), rel_ci)):
            missing = [k for k in keys if k not in exec_text]
            if missing:
                err(f"运行环境防线被破坏：{rel_exec} 缺失 {missing}——必加载层须有一行引用"
                    f"（该层每次会话无条件加载；缺则本条在非流水线场景读不到）：见 {desc}",
                    rel_exec)
    else:
        err(f"缺少 {rel_exec}——运行环境条在必加载层的引用无从核对", rel_exec)

    for rel, key, desc in (
        ("specs/general/verify.adoc", RUNTIME_ENV_SECTION,
         "验证侧须指向本条（验证时的环境一致性是验证成立的前提）"),
        ("specs/general/planning.adoc", "基线",
         "基线侧须指向本条（基线必须在项目声明的环境下取得，否则统计不可比）"),
    ):
        fp = os.path.join(REPO_ROOT, *rel.split("/"))
        if not os.path.isfile(fp):
            err(f"缺少 {rel}——运行环境条在该处的引用无从核对", rel)
            continue
        with open(fp, encoding="utf-8") as fh:
            body = fh.read()
        if RUNTIME_ENV_SECTION not in body:
            err(f"运行环境防线被破坏：{rel} 未指向「{RUNTIME_ENV_SECTION}」——{desc}",
                rel)

    # 调度器识别特征：有声明落点/要跑构建测试即加载（缺则该条永远不会被触发加载）
    common_path = os.path.join(REPO_ROOT, "AGENTS_COMMON.adoc")
    if os.path.isfile(common_path):
        with open(common_path, encoding="utf-8") as fh:
            common = fh.read()
        for keys, desc in ((("识别特征", RUNTIME_ENV_SECTION),
                            "加载调度器须有本条的加载项与识别特征（如项目有声明运行环境的落点、"
                            "要跑构建/测试/脚本）——缺则该条永远不会被加载，规则实际失效"),
                           (("换个版本也能跑通",), "调度器条目须保留「换版本也能跑通也不得换」的口径"),
                           (("java.version", ".nvmrc", "python-version"),
                            "调度器条目须点出声明落点的常见形态（否则执行者不知道去哪取值）")):
            missing = [k for k in keys if k not in common]
            if missing:
                err(f"运行环境防线被破坏：AGENTS_COMMON.adoc 缺失 {missing}——{desc}",
                    "AGENTS_COMMON.adoc")
    else:
        err("缺少 AGENTS_COMMON.adoc——运行环境的调度器登记无从核对", "AGENTS_COMMON.adoc")

    # 维护方落点：工具声明清单 + 依据入馆（同义性差异：本条严于标准）
    for rel, keys, desc in (
        ("AGENTS.adoc", (RUNTIME_ENV_SECTION, "运行环境防线"),
         "维护方工具声明清单须登记该防线（文档↔脚本一致）"),
        ("library/adoption.adoc", (RUNTIME_ENV_SECTION, "同义性差异"),
         "依据图书馆须记该条的同义性差异（本条严于外部材料：标准未规定「必须使用声明的那一个"
         "环境」，属本集合的判据化取舍）"),
    ):
        fp = os.path.join(REPO_ROOT, *rel.split("/"))
        if not os.path.isfile(fp):
            err(f"缺少 {rel}——运行环境条的落点无从核对", rel)
            continue
        with open(fp, encoding="utf-8") as fh:
            body = fh.read()
        missing = [k for k in keys if k not in body]
        if missing:
            err(f"运行环境防线被破坏：{rel} 缺失 {missing}——{desc}", rel)
    phase_done()


def check_registry_mirror_guard():
    """『包源与镜像源防线』：推荐的包源地址**已实测可用**、且**换源有次序与降级边界**。

"""
    phase("包源与镜像源防线检查")
    rel = "specs/general/dependency.adoc"
    path = os.path.join(REPO_ROOT, *rel.split("/"))
    if not os.path.isfile(path):
        err(f"缺少 {rel}——包源的选用次序与降级边界失去集中落点", rel)
        phase_done()
        return
    with open(path, encoding="utf-8") as fh:
        text = fh.read()
    section = _section_text(text, REGISTRY_SECTION)
    if not section:
        err("依赖规范缺少「包源（包仓库/镜像站）的选用」节——"
            "换源会重新变成'凭感觉挑一个'：不按次序、不先实测、覆盖引用方既有配置", rel)
        phase_done()
        return
    for name, tokens, why in REGISTRY_ANCHORS:
        for token in tokens:
            if token not in section:
                err(f"「包源（包仓库/镜像站）的选用」节缺少要点：{name}"
                    f"（应含 `{token}`）——{why}", rel)
    # 技术栈/平台侧落点：具体源地址与现场判据须有着落
    for rel2, anchor, why in (
            ("specs/stack/maven.adoc", "mirrors.cloud.tencent.com/nexus/repository/maven-public/",
             "Maven 侧的具体源与 `mirrorOf` 写法须有落点（check_maven_mirror_guard 另钉其前提与边界）"),
            ("specs/stack/python.adoc", "pypi/simple",
             "Python 侧的 pip 源须有落点（否则本条只停在通用层、到不了使用现场）"),
            ("specs/stack/java.adoc", "clojars",
             "Clojars 等'中央仓镜像不能替代'的源须有落点（实测：坐标归属搞错会被误判为镜像失效）"),
            ("specs/general/ci-cd.adoc", "包源（包仓库/镜像站）的选用",
             "CI 侧的镜像/运行时/系统包取源须与通用层次序同源（缺则流水线仍会直连境外源）"),
            ("specs/platform/cnb.adoc", "包源与镜像源",
             "平台侧须写清'优先用平台内已优化的源 + 镜像加速地址以实测为准'"),
            ("library/mirrors.adoc", "实测记录",
             "依据图书馆须记录实测取值与取样条件（缺则'先实测'这条落不了地、后人无从复核）"),
    ):
        p2 = os.path.join(REPO_ROOT, *rel2.split("/"))
        if not os.path.isfile(p2):
            err(f"{rel2} 缺失——{why}", rel2)
            continue
        with open(p2, encoding="utf-8") as fh:
            t2 = fh.read()
        if anchor not in t2:
            err(f"{rel2} 缺少『{anchor}』——{why}", rel2)
    # 图书馆入口登记（写文件与登记是同一动作）
    idx = os.path.join(REPO_ROOT, "library", "README.adoc")
    if os.path.isfile(idx):
        with open(idx, encoding="utf-8") as fh:
            if "link:mirrors.adoc[]" not in fh.read():
                err("图书馆入口未登记 mirrors.adoc——登记与实际不一致，"
                    "读者按入口找不到这条依据（写文件与登记是同一个动作）", "library/README.adoc")
    # 图书馆主题集合的登记一致性：新增主题时"写文件"须与"登记到入口表"同动作。
    # 另核一件事——**入口表的登记集合 ⊇ 磁盘实际主题文件集合**（漏登记即"文件在、
    # 读者按入口找不到"，而 check_library_guard 只在下限常量被改坏时才拦得住；
    # 既有主题 `quality.adoc` 就不在下限常量里，正说明下限常量不能当完整性来源）。
    lib_root = os.path.join(REPO_ROOT, "library")
    if os.path.isdir(lib_root):
        actual_topics = {f for f in os.listdir(lib_root)
                         if f.endswith(".adoc") and f != "README.adoc"}
        idx_txt = ""
        if os.path.isfile(idx):
            with open(idx, encoding="utf-8") as fh:
                idx_txt = fh.read()
        registered = set(re.findall(r"^\| link:([^\[\]]+\.adoc)\[", idx_txt, re.M))
        for missing_topic in sorted(actual_topics - registered):
            err(f"图书馆主题 {missing_topic} 未登记到入口表——"
                "读者按入口找不到这条依据（写文件与登记是同一个动作）", "library/README.adoc")
    # 图书馆依据主题本体：mirrors.adoc 的要点（同义性差异、本站取舍、实测/未确证标注）
    lib = os.path.join(lib_root, "mirrors.adoc")
    if os.path.isfile(lib):
        with open(lib, encoding="utf-8") as fh:
            lt = fh.read()
        for name, token in REGISTRY_LIBRARY_ANCHORS:
            if token not in lt:
                err(f"library/mirrors.adoc 缺少要点：{name}（应含 `{token}`）——"
                    "缺则本站取舍会被读成外部标准原文、或实测数字会被当成人人适用的结论", "library/mirrors.adoc")
    phase_done()


def check_throughput_guard():
    """『执行吞吐』防线：轮次纪律的判据、常驻层引用与调度器登记不得被删。

"""
    phase("执行吞吐防线检查")
    rel = "specs/general/context.adoc"
    path = os.path.join(REPO_ROOT, *rel.split("/"))
    if not os.path.isfile(path):
        err(f"{rel} 缺失——执行吞吐判据无落点", rel)
        phase_done()
        return
    with open(path, encoding="utf-8") as fh:
        text = fh.read()
    section = _section_text(text, "执行吞吐")
    if not section:
        err("context.adoc 缺少「执行吞吐」节——轮次纪律的判据失去落点（只有读取范围时，"
            "执行者会把可合并的调用拆成多轮，每轮重付一次全上下文输入）", rel)
        phase_done()
        return
    required = [
        ("独立调用合并（L1）", "独立调用必须合并"),
        ("试探式往返的判定标准", "试探式往返"),
        ("构建/校验输出一次取到（L1）", "构建与校验的输出须一次取到"),
        ("读到即沉淀、不重复读", "不重复读"),
        ("往返成本入规划", "往返成本也要算"),
        ("凭据一次固化", "固化为可复用形态"),
        ("缓存与镜像就近、不重配", "不覆盖、不重配"),
        ("长流程不留零信息等待（L1）", "零信息等待"),
        # 用户提出的要件「相同内容不得重复读取」在**留证侧**的落点：判定标准要可核对，
        # 不能只有一句"不重复读"。缺「判定标准」时该条退化成自觉要求（本轮补）。
        ("不重复读的判定标准（可核对）", "同一路径在一次任务里被读第二次"),
    ]
    for name, token in required:
        if token not in section:
            err(f"「执行吞吐」节缺少要点：{name}（应含 `{token}`）", rel)

    # 平台侧（CNB）：两处特有代价（一次唤起=一次完整加载、状态与用量按汇总先取再下钻）
    plat = os.path.join(REPO_ROOT, "specs", "platform", "cnb.adoc")
    if os.path.isfile(plat):
        with open(plat, encoding="utf-8") as fh:
            ptext = fh.read()
        psec = _section_text(ptext, "执行吞吐")
        if not psec:
            err("cnb.adoc 缺少「执行吞吐（平台侧的两处特有代价）」节——"
                "平台侧特有代价（一次唤起=一次完整加载、状态查询逐轮付一次往返）"
                "失去落点，执行者会为刷新长流程而反复另起一轮", "specs/platform/cnb.adoc")
        else:
            for name, token in (("一次唤起=一次完整加载（L1）", "一次唤起 = 一次完整加载 + 一轮往返"),
                                ("状态按汇总先取再下钻（L2）", "先取汇总、再按需下钻"),
                                ("不空转等待（同一形态的现场）", "零信息"),
                                ("AI 用量与请求明细是可观测面（L2）", "AI 用量汇总")):
                if token not in psec:
                    err(f"cnb.adoc「执行吞吐」节缺少要点：{name}（应含 `{token}`）",
                        "specs/platform/cnb.adoc")
    else:
        err("缺少 specs/platform/cnb.adoc——平台侧执行吞吐条无从核对", "specs/platform/cnb.adoc")

    for rel2, keys, desc in (
        ("specs/core/execution.adoc",
         ("执行吞吐", "少绕"),
         "常驻层（最高关注项段落与「任务编排与上下文管理」）须点到执行吞吐，"
         "否则每次会话加载到的常驻层里没有这条纪律"),
        ("AGENTS_COMMON.adoc",
         ("执行吞吐", "多次往返"),
         "加载调度器须有本条的加载项与识别特征（多步命令/构建/轮询、预计需多次往返），"
         "否则它永远不会被触发加载"),
    ):
        fp = os.path.join(REPO_ROOT, *rel2.split("/"))
        if not os.path.isfile(fp):
            err(f"缺少 {rel2}——执行吞吐条在该处的落点无从核对", rel2)
            continue
        with open(fp, encoding="utf-8") as fh:
            body = fh.read()
        missing = [k for k in keys if k not in body]
        if missing:
            err(f"执行吞吐防线被破坏：{rel2} 缺失 {missing}——{desc}", rel2)
    phase_done()


