def check_performance_guard():
    """『性能测试防线』：测量与记录两半的要点不得被删或降级。

"""
    phase("性能测试防线检查")
    path = os.path.join(REPO_ROOT, *PERF_SPEC.split("/"))
    if not os.path.isfile(path):
        err(f"缺少 {PERF_SPEC}——性能测试判据无处承载（公共测试规范是它的唯一落点）", PERF_SPEC)
        phase_done()
        return
    with open(path, encoding="utf-8") as fh:
        text = fh.read()
    section = _section_text(text, PERF_SECTION)
    if not section:
        err("公共测试规范缺少「性能测试」节——测量与记录判据失去落点"
            "（性能测试会退回\"跑一次看看谁快\"）", PERF_SPEC)
        phase_done()
        return
    for name, anchors, why in PERF_SECTION_ANCHORS:
        for token in anchors:
            if token not in section:
                err(f"「性能测试」节缺少要点：{name}（应含 `{token}`）——{why}", PERF_SPEC)

    # 调度器：本条的加载项与识别特征（缺则它永远不会被触发加载、规则实际失效）
    with open(os.path.join(REPO_ROOT, "AGENTS_COMMON.adoc"), encoding="utf-8") as fh:
        generic = fh.read()
    disp = next((ln for ln in generic.splitlines()
                 if "specs/general/testing.adoc" in ln and "性能测试" in ln), "")
    if not disp:
        err("加载调度器缺少性能测试的加载项与识别特征（应含『性能测试』字样）——"
            "缺则它永远不会被触发加载、判据实际失效", "AGENTS_COMMON.adoc")
    else:
        for token in ("性能测试", "性能敏感", "方案组合"):
            if token not in disp:
                err(f"加载调度器性能测试条目缺少识别特征 `{token}`——"
                    "触发特征不全时，执行者会\"没想到要做性能测试\"", "AGENTS_COMMON.adoc")

    # Java 栈：承载与执行边界（不得混入常规 test 阶段）
    jpath = os.path.join(REPO_ROOT, *PERF_JAVA.split("/"))
    if not os.path.isfile(jpath):
        err(f"缺少 {PERF_JAVA}——`PerfTests` 的承载与执行边界无处说明", PERF_JAVA)
    else:
        with open(jpath, encoding="utf-8") as fh:
            jtext = fh.read()
        for token in ("`PerfTests`（性能）", "性能测试", "不混入常规 `test` 阶段"):
            if token not in jtext:
                err(f"{PERF_JAVA} 的「启动型与端到端测试」缺少要点 `{token}`——"
                    "承载/执行边界被删会让 `PerfTests` 被 surefire 误跑或被当成常规测试统计",
                    PERF_JAVA)

    # 图书馆依据主题：外部材料与"本站取舍"的分界（依据不得只剩名称）
    lpath = os.path.join(REPO_ROOT, *PERF_LIBRARY.split("/"))
    if not os.path.isfile(lpath):
        err(f"缺少 {PERF_LIBRARY}——性能测试判据的依据无处承载"
            "（\"至少 3 次采样\"\"必留未选方案\"这类取值将无从核对，也会被误读成标准规定）",
            PERF_LIBRARY)
    else:
        with open(lpath, encoding="utf-8") as fh:
            ltext = fh.read()
        for token in PERF_LIBRARY_ANCHORS:
            if token not in ltext:
                err(f"{PERF_LIBRARY} 缺少依据锚点 `{token}`——"
                    "依据被压成名称后，读者无法区分\"外部材料要求\"与\"本集合自己的取舍\"",
                    PERF_LIBRARY)
    phase_done()


# 防线清单表（`specs-project-maintainer/guards.adoc`）里每行的形态：`| 序号 | \`防线名\` | 用途 |`
GUARDS_MANIFEST_ROW = re.compile(r"^\|\s*(\d+)\s*\|\s*`(check_[a-z0-9_]+)`\s*\|", re.M)


# 调度器里**允许出现的细节类型**：文件路径引用、加载触发特征（可判读的识别特征）、以及
# "该文件承载什么主题"的一句话。**不允许**把该文件的条目清单、判定标准、取值面抄进来——
# 那会让调度器成为上游落点（`specs/general/terminology.adoc`「数据字典」的「反膨胀」：
# 上游落点不得因收录下游细节而显著变大），且与 §数据字典「只引名称」相抵。
DISPATCHER_DETAIL_MARKERS = (
    "判定标准", "任一命中", "判据见", "适用面（L1", "例外（L1", "边界（L1",
    "本文件不复述", "唯一落点", "不得降级",
)


def check_dispatcher_no_details_guard():
    """『调度器不承担细节』：加载调度器只登记"哪个文件 + 何时加载"，不抄该文件的条目。

    **为什么需要它**：调度器的加载项曾被逐项扩写成"小抄"——把一个文件的条目名、适用面、
    例外与边界成串写在那一行里（本仓库实测：最长一条 815 字符、单文件 3 KB 的条目清单被
    抄进常驻层）。三处危害：① 常驻层被下游细节撑大（每次会话都付上下文）；② **抄一遍就是
    第二处会各自漂移的正文**（改了下游忘了改调度器，执行者按调度器理解会走错）；
    ③ 与《数据字典》的「反膨胀」（上游落点不得被下游细节撑大）直接相抵。

    **判据（可机械核对）**：调度器各层的加载项里不得出现**条目级**细节词；允许写的是
    文件路径、加载触发特征、"该文件承载的主题"。**边界（防误伤）**：识别特征本身可以很长
    （它必须可判读），故本条只拦"判定标准/任一命中/例外"这类**条目内部**的措辞。
    """
    phase("调度器不承担细节检查（只登记，不抄条目）")
    if not os.path.isfile(GENERIC_FILE):
        err("找不到 AGENTS_COMMON.adoc，无法核对调度器条目形态", "AGENTS_COMMON.adoc")
        phase_done()
        return
    with open(GENERIC_FILE, encoding="utf-8") as fh:
        text = fh.read()
    m = re.search(r"== 分类与懒加载（加载调度器）(.*?)== 技术栈扩展约定", text, re.S)
    if m is None:
        err("AGENTS_COMMON.adoc 未找到「分类与懒加载（加载调度器）」节——"
            "条目形态核对失去落点", "AGENTS_COMMON.adoc")
        phase_done()
        return
    bad = []
    for lineno, line in enumerate(m.group(1).split("\n"), 1):
        if not line.startswith("* "):
            continue
        for marker in DISPATCHER_DETAIL_MARKERS:
            if marker in line:
                bad.append((lineno, marker, line[:60]))
    if bad:
        for lineno, marker, head in bad:
            err(f"调度器加载项出现条目级细节词『{marker}』（`{head}…`）——"
                "调度器只写『哪个文件 + 何时加载』，条目清单/判定标准/适用面与例外写在该文件里；"
                "抄进调度器就是第二份会各自漂移的正文，还把常驻层撑大"
                "（判据见 specs/general/terminology.adoc「反膨胀」与 specs/general/doc.adoc"
                "「名称的定义按作用域归档、引用只写名称」）", "AGENTS_COMMON.adoc", lineno)
    else:
        log("  调度器条目形态合规：只登记文件与触发特征，未抄条目细节")
    phase_done()


def check_ledger_source_paths_guard():
    """『台账来源列须指向真实文件』：`check_effective.py` 的每条来源都要能打开。

    **为什么需要它**：台账的来源列曾被写成集束引用（`文件A + specs/general/testing.adoc`），
    而**判据其实不在那个文件里**（本仓库实测：9 条来源写 `specs/general/testing.adoc`，
    实际判据在 `verify.adoc` / `context.adoc`）。来源指错时，读者按它去核对会读到
    "这个文件里没有这条"——台账因此从"可核对"退化成"看着像有出处"。

    **判据（可机械核对）**：台账每条的来源列里出现的每个 `*.adoc` 路径**都必须真实存在**；
    集束引用（`A + B`）按其列出的每个路径逐一看。**边界**：本条不管"来源指得对不对"
    （那是语义判断，交人/子 agent 复核），只管"指的那个文件在不在"。
    """
    phase("台账来源路径检查（来源列须指向真实文件）")
    rel = "script/check_effective.py"
    if not os.path.isfile(os.path.join(REPO_ROOT, *rel.split("/"))):
        err(f"找不到 {rel}——台账来源无从核对", rel)
        phase_done()
        return
    src = _read_script_src(rel) or ""
    bad = []
    for entry in re.finditer(r'^\s{4}\(\s*"([^"]+)",\s*\n?\s*"([^"]+)"', src, re.M):
        name, source = entry.group(1), entry.group(2)
        for path in re.findall(r"[A-Za-z0-9_./-]+\.adoc", source):
            if not os.path.isfile(os.path.join(REPO_ROOT, *path.split("/"))):
                bad.append((name, path))
    if bad:
        for name, path in bad:
            err(f"台账条目『{name}』的来源 `{path}` **不存在**——"
                "来源指错时读者按它核对会读到『这个文件里没有这条』，台账从可核对退化"
                "成看着像有出处；请改成判据真正所在的那个文件", rel)
    else:
        log("  台账来源路径合规：每条来源指向的文件都存在")
    phase_done()


def check_guard_order_guard():
    """『防线次序与清单表一致』：`CHECKS` 的执行次序必须 = 防线清单表里的次序。

    为什么需要它：次序此前只存在于 `main()` 正文的行序里，**改一处位置没有任何判据**
    （实测：把某道防线从编排中段移到末尾，脚本与 985 条单测全绿）。本轮把次序提成
    显式的 `CHECKS` 序列，再由本防线与 `specs-project-maintainer/guards.adoc` 逐行对账。

    判据（三条）：① 两处的防线名逐一相同且次序一致；② 清单表的序号连续；③ 条数相同。
    """
    phase("防线次序与清单表一致性检查（`CHECKS` ↔ guards.adoc）")
    # `_read_script_src` 以"相对仓库根路径"为缓存键：夹具换根后仍可能命中上一轮的值，
    # 故本条核脚本自身的场景（与本文件同路径）须显式清该键，否则"脚本缺失"的场景
    # 会静默读到本文件自己的 `CHECKS`（本仓库实测：该反例反而报了"次序不一致"）。
    REPO_SCRIPT_SRC_CACHE.pop("script/check_specs.py", None)
    src = _read_script_src("script/check_specs.py") or None
    if src is None:
        err("找不到 script/check_specs.py，无法核对防线次序", "script/check_specs.py")
        phase_done()
        return
    seq = re.findall(r"(?m)^ {4}(check_[a-z0-9_]+),$", _checks_block(src))
    if not seq:
        err("script/check_specs.py 缺少 `CHECKS` 序列——防线次序失去唯一来源", "script/check_specs.py")
        phase_done()
        return
    # 路径**按当前的 `PROJECT_SPECS_DIR` 现算**，不在模块级固化：模块常量在 import 时
    # 就绑定了当时的仓库根，夹具换根后它仍指向真实仓库——于是"清单表缺失"这类反例
    # 会静默读到真文件（本仓库实测：该防线在夹具里怎么改都读不到夹具内容）。
    manifest_path = os.path.join(PROJECT_SPECS_DIR, "guards.adoc")
    if not os.path.isfile(manifest_path):
        err("缺少 specs-project-maintainer/guards.adoc——防线清单（有哪些防线、按什么次序跑）"
            "失去落点；`CHECKS` 的次序没有任何可读处，改次序时意图无从追溯",
            "specs-project-maintainer/guards.adoc")
        phase_done()
        return
    with open(manifest_path, encoding="utf-8") as fh:
        manifest = fh.read()
    rows = GUARDS_MANIFEST_ROW.findall(manifest)
    if not rows:
        err("specs-project-maintainer/guards.adoc 未找到「执行次序与用途」表——"
            "次序核对失去判据（表被改写或删掉时须报红，不得静默放行）",
            "specs-project-maintainer/guards.adoc")
        phase_done()
        return
    nums = [int(n) for n, _ in rows]
    names = [n for _, n in rows]
    if nums != list(range(1, len(nums) + 1)):
        err(f"防线清单表序号不连续：{nums[:8]}…（共 {len(nums)} 行）——"
            "序号断了说明有条目被整条删掉；删条目须连带改序号并说明"
            "（否则读者按序号核对照点时，缺的那一项无从发现）",
            "specs-project-maintainer/guards.adoc")
    if names != seq:
        only_seq = [n for n in seq if n not in names]
        only_manifest = [n for n in names if n not in seq]
        detail = []
        if only_seq:
            detail.append(f"只在 `CHECKS` 里：{only_seq}")
        if only_manifest:
            detail.append(f"只在清单表里：{only_manifest}")
        if not detail:
            # 两处**集合相同、次序不同**是最难发现的一种：逐行对账要给出第一处分叉，
            # 否则报错信息只说"不一致"、修的人得自己逐行比 89 行（实测形态：对调两道防线）。
            i = next(j for j, (a, b) in enumerate(zip(seq, names)) if a != b)
            detail.append(f"第 {i + 1} 处起次序不同：`CHECKS` 是 {seq[i]}、清单表是 {names[i]}")
        err("防线次序不一致：`script/check_specs.py` 的 `CHECKS` 序列与 "
            "specs-project-maintainer/guards.adoc 的清单表不是同一串（" + "；".join(detail)
            + "）——次序是刻意安排的，两处必须逐一同序；改一侧就必须同步另一侧"
            "（本轮实测：把某道防线从编排中段移到末尾，脚本与全部单测全绿、无人发现）",
            "specs-project-maintainer/guards.adoc")
    else:
        log(f"  防线次序与清单表一致：{len(seq)} 道，逐一同序")
    phase_done()


def check_wiring_guard():
    """『防线接线完整性』：`CHECKS` 序列里的每道防线都须真实存在、每个已定义防线都须可达。

    两条判据都可机械核对：① 序列里的每个名字都有函数定义；② 每个已定义的 `check_*`
    都在序列里**直接列出、或经序列中某防线的函数体可达**（闭包口径与 `check_guard_manifest`
    一致——两处各写一套会出现"接线的说跑了、台账的说没跑"）。
    **次序不在此判**：`CHECKS` 就是次序的唯一来源，它与
    `specs-project-maintainer/guards.adoc` 清单表的一致性由 `check_guard_order_guard` 守。
    """
    phase("防线接线完整性检查（定义了必须被执行）")
    src = _read_script_src("script/check_specs.py")
    if src is None:
        err("找不到 script/check_specs.py，无法核对防线接线", "script/check_specs.py")
        phase_done()
        return
    if not _checks_block(src).strip():
        err("script/check_specs.py 缺少 `CHECKS` 序列——防线的执行次序失去唯一来源，"
            "接线与次序都无从核对（次序是刻意安排的，不得靠 `main()` 正文里的行序隐式表达）",
            "script/check_specs.py")
        phase_done()
        return
    defined = set(re.findall(r"(?m)^def (check_[a-z0-9_]+)\(", src))
    wired = _guard_wired_closure(src)
    unwired = sorted(defined - wired)
    orphan = sorted(wired - defined)
    if unwired:
        err("防线接线不完整：以下 check_* 已定义但任何地方都不会被执行（"
            + "、".join(unwired) + "）——既不在 `CHECKS` 序列里、也不被序列中任何防线调用，"
            "即『定义了却不执行』：check_specs.py 与配套测试都会全绿而它一次也没跑过",
            "script/check_specs.py")
    if orphan:
        err("`CHECKS` 序列点名了不存在的防线：" + "、".join(orphan)
            + "——接线与实现不一致", "script/check_specs.py")
    if not unwired and not orphan:
        log(f"  防线接线完整：{len(defined)} 道防线全部会被执行")
    phase_done()


# 图书馆（仓库根 `library/`，**不在默认引用面内**）：其价值全在"依据真的
# 能查到、真的对得上"——入口登记的主题文件必须真实存在，外部标准的**逐字引文**必须仍在
# （少一句就意味着"依据被压成名称"）。图书馆不在默认引用面内（本仓库内容全部会发布，
# 但引用方按公共输入加载时取不到它、其项目里也没有本仓库的文件），故"内容会被分发"一类
# 约束不按公共内容口径适用；剩下的是**本仓库自己的完整性**：有没有、登记是否双向一致、
# 引文还在不在、文件里的引用是否真能解析（引用方看不到这里，引用悬空只有本仓库自己能发现）。
# 判定只认机械可判定的形态：文件/片段存在性与引用可解析性；"该依据是否真的支持该条、
# 依据找得全不全"属语义判断，交人/子 agent 复核承担（见 specs/general/verify.adoc「验证总纲」）。
# **取样来源标记**：图书馆的每条外部依据都须带"它是怎么被取回的"标记——这是"不划水、
# 不造假"的判据落点。三类标记缺任一类，就意味着某类依据的**可信度边界**无从判断
# （"官方文本已取回"可复取比对 vs "官方网页已取回"仅题名可对 vs "未逐字取回"不引其字句）。
# 常量化后由 check_library_guard 机械钉住：标记整体被删（依据被悄悄压成"看起来很权威的
# 名称"）即报错——grep 在 sources.adoc 命中只说明文档正文举例还在，不等于防线覆盖到它。
LIBRARY_SOURCE_MARKERS = (
    "官方文本已取回",
    "官方网页已取回",
    "未逐字取回",
)


def _lib_resolve(target: str):
    """把馆内引用的写法解析为**仓库根相对路径**（单一基准），无法解析/越界则返回 None。

    基准口径（与反引号写法一致，见 check_library_guard 的"引用可解析"条）：
      1. 先按**仓库根**解析（`CHANGELOG.adoc`、`AGENTS_COMMON.adoc`、`specs/general/doc.adoc`）
         —— 与 Asciidoctor.js 渲染的文档站一致（`link:` 按文档源所在目录解析，文档在仓库根）；
      2. 未命中再按**本文件所在目录**解析（`../specs/...` 这类真正离开 `library/` 的写法）。

    **同一写法只有一个基准**：历史实现里反引号按仓库根、`link:` 按本文件目录，
    结果同一句引用 `CHANGELOG.adoc` 的两种写法在"文件存在/不存在"上给出相反结论。
    """
    t = target.strip()
    if not t or t.startswith("#"):
        return None
    if re.match(r"^[a-zA-Z][a-zA-Z0-9+.-]*://", t):
        return None
    if t.startswith("/"):
        return None                       # 根绝对路径：格式问题单独报，不进存在性核对
    is_dir = t.endswith("/")
    repo_rel = posixpath.normpath(t).replace("\\", "/")
    if repo_rel != ".." and not repo_rel.startswith("../"):
        if is_dir:
            if os.path.isdir(os.path.join(REPO_ROOT, *repo_rel.split("/"))):
                return repo_rel + "/"
        elif os.path.isfile(os.path.join(REPO_ROOT, *repo_rel.split("/"))):
            return repo_rel
    local = posixpath.normpath(posixpath.join("library", t)).replace("\\", "/")
    if local == ".." or local.startswith("../"):
        return repo_rel                  # 越出仓库根：返回仓库根解析结果，交由存在性判定报错
    return local + "/" if (is_dir and not local.endswith("/")) else local


def _check_library_target(m: str, desc: str, rel: str, j: int, allow_escape: bool = False):
    """核对一条馆内引用的落点是否为**本仓库内真实存在的文件/目录**。

    `m` 为写法（反引号内的路径或 `link:` 目标）；`desc` 为报错里的引用描述。
    """
    if _is_placeholder_ref(m):
        return
    is_dir = bool(m.endswith("/"))
    resolved = _lib_resolve(m)
    if resolved is None:
        return
    if resolved == ".." or resolved.startswith("../"):
        if allow_escape:
            err(f"{desc} 越出仓库根——馆内引用须指向本仓库内的真实文件", rel, j)
        return
    if is_dir:
        if not os.path.isdir(os.path.join(REPO_ROOT, *resolved.rstrip("/").split("/"))):
            err(f"{desc} 指向不存在的目录——悬空引用等于依据链断在这里", rel, j)
        return
    if not os.path.isfile(os.path.join(REPO_ROOT, *resolved.split("/"))):
        err(f"{desc} 指向不存在的文件——"
            "悬空引用等于依据链断在这里（公共内容里的死链判据与它无关："
            "图书馆不在默认引用面内，读者在本仓库内，故按仓库根基准核对）", rel, j)


# 根级文件名白名单（馆内以 `xxx.adoc` / `xxx.py` 形态引用本仓库根或已知目录下的文件时，
# 只有在此列内的写法才被当作"路径"核对存在性——防止把普通词/文件名约定当路径误报）。
_LIB_ROOT_FILES = ("AGENTS.adoc", "AGENTS_COMMON.adoc", "AGENTS.md", "PUBLIC.adoc",
                   "README.adoc", "PROMPTS.adoc", "CHANGELOG.adoc", "INSTALL.adoc",
                   "check_specs.py", "check_effective.py", "clean_tmp.py",
                   "_common.txt", "review.adoc", "refactor.adoc")
LIBRARY_QUOTE_ANCHORS = (
    "Software Reviews and Audits",
    "IEEE Standard for Information Technology--Systems Design--Software Design Descriptions",
    "Software and systems engineering — Software testing — Part 4: Test techniques",
    "Systems and software Quality Requirements and Evaluation (SQuaRE) — Product quality model",
    "ISO/IEC Directives, Part 2 — Principles and rules for the structure and drafting",
    "Ergonomics of human-system interaction — Part 110: Interaction principles",
    "Key words for use in RFCs to Indicate Requirement Levels",
    "Ambiguity of Uppercase vs Lowercase in RFC 2119 Key Words",
    "UTF-8, a transformation format of ISO 10646",
    "Date and Time on the Internet: Timestamps",
    "The OAuth 2.0 Authorization Framework",
    "Best Current Practice for OAuth 2.0 Security",
    "The 'Basic' HTTP Authentication Scheme",
    "Digital Identity Guidelines: Authentication and Lifecycle Management",
    "Deserialization of Untrusted Data",
    "Observable Timing Discrepancy",
    "Generation of Error Message Containing Sensitive Information",
    "Active Debug Code",
    "Dependency specification for Python Software Packages",
    "Style Guide for Python Code",
    "Docstring Conventions",
    "**/IT*.java",
    "**/*ITCase.java",
    "**/*TestCase.java",
    "MAJOR version when you make incompatible API changes",
    "In many IETF documents, several words",
    "when they are in all capitals as shown below",
) + LIBRARY_SOURCE_MARKERS


def check_library_guard():
    """『图书馆防线』：依据须查得到、对得上、引用不悬空（不在默认引用面内的内容）。

"""
    phase("图书馆防线检查")
    if not os.path.isfile(LIBRARY_INDEX):
        err("缺少图书馆入口 library/README.adoc——"
            "规范条目与项目决策背后的依据将只剩名称、无从核对"
            "（本仓库为根目录 library/；注意它不是\"未发布\"，站点与仓库都发布它，"
            "它只是不属默认引用面——见 AGENTS.adoc「依据图书馆」）",
            "library/README.adoc")
        phase_done()
        return

    with open(LIBRARY_INDEX, encoding="utf-8") as fh:
        index_text = fh.read()
    with open(PROJECT_FILE, encoding="utf-8") as fh:
        project_entry = fh.read()

    # 1) 项目规范入口登记：图书馆入口须在 AGENTS.adoc 被登记
    if "library/README.adoc" not in project_entry:
        err("图书馆未在本仓库项目规范入口（AGENTS.adoc）登记——"
            "读者无从知道何时该加载它，依据实际不可达"
            "（写文件与登记是同一个动作）",
            "AGENTS.adoc")

    # 2) 入口登记的主题 ↔ 主题目录实际文件，双向一致
    registered = set(re.findall(r"link:([^\[\]]+\.adoc)\[", index_text))
    actual = set()
    if os.path.isdir(LIBRARY_DIR):
        actual = {f for f in os.listdir(LIBRARY_DIR)
                  if f.endswith(".adoc") and f != "README.adoc"}
    for r in sorted(registered):
        if not os.path.isfile(os.path.join(LIBRARY_DIR, r)):
            err(f"图书馆入口登记了不存在的主题文件: {r}——"
                "读者按入口找不到依据（登记与实际不一致）", "library/README.adoc")
    for a in sorted(actual - registered):
        err(f"图书馆存在未登记的主题文件: {a}——"
            "未登记即不会被读者发现，依据实际不可达（写文件与登记是同一个动作）",
            "library/README.adoc")
    # 下限补丁（已知局限性）：`LIBRARY_TOPICS` 只保证"这几个主题必须有"，不表达"应有哪些
    # 主题"——主题集合的完整来源仍是入口登记表（上一步已双向核对）。故"某主题该不该有、
    # 有没有被悄悄漏掉"属语义判断，交人/子 agent 复核；此处不做也不假装做。
    for t in LIBRARY_TOPICS:
        if t not in actual:
            err(f"图书馆缺少主题文件: {t}", "library/README.adoc")

    # 3) 逐字引文锚点：依据不得只剩名称
    texts = {}
    for f in sorted(actual):
        with open(os.path.join(LIBRARY_DIR, f), encoding="utf-8") as fh:
            texts[f] = fh.read()
    blob = "\n".join(texts.values())
    missing = [q for q in LIBRARY_QUOTE_ANCHORS if q not in blob]
    if missing:
        err(f"图书馆缺失逐字引文锚点 {missing}——依据被压成名称后将无从核对"
            "（判据：所引标准的关键片段须能在馆内逐字找到）",
            "library/README.adoc")

    # 3b) 『规范准入与自身取舍』主题的要点锚点：该主题的关键不是"引到某段标准原文"，
    # 而是"如实写明本集合自己的取舍与外部材料的差异"。缺这几句，依据仍能凑齐，
    # 但读者会把本站更严取舍/组织约定读成标准规定——这正是该主题存在的理由。
    if "adoption.adoc" in actual:
        adoption_text = texts.get("adoption.adoc", "")
        miss_adoption = [q for q in _LIBRARY_ADOPTION_ANCHORS if q not in adoption_text]
        if miss_adoption:
            err(f"图书馆『规范准入与自身取舍』主题缺失要点锚点 {miss_adoption}——"
                "同义性差异与取舍判据被删后，本站更严取舍会被读成外部标准原文"
                "（依据不实，见 specs/general/source.adoc「外部引用」）",
                "library/adoption.adoc")

    # 3c) 『依据的写入与关联』主题的要点锚点：该主题的价值全在"写入有触发判据、反查有可执行
    # 算法"——缺这几句，"写依据"重新变成靠自觉（不主动写、写什么凭发挥），或把规则本体抄进馆
    # （第二真源，改一处必漏一处）；解析算法被删则又回到"遍历项目找依据"。
    if "usage.adoc" in actual:
        usage_text = texts.get("usage.adoc", "")
        miss_usage = [q for q in _LIBRARY_USAGE_ANCHORS if q not in usage_text]
        if miss_usage:
            err(f"图书馆『依据的写入与关联』主题缺失要点锚点 {miss_usage}——"
                "写入触发判据与反查解析算法被删后，依据的写入重新靠自觉、"
                "关联重新退化成'凭印象检索'",
                "library/usage.adoc")

    # 4) 引用可解析：馆内引用按仓库根基准解析（悬空引用 = 依据链断在这里）
    for f in sorted(actual) + ["README.adoc"]:
        path = os.path.join(LIBRARY_DIR, f)
        with open(path, encoding="utf-8") as fh:
            lines = fh.readlines()
        rel = f"library/{f}"
        for j, line in enumerate(lines, 1):
            # 反引号写法：`specs/...`（按仓库根解析；`library/...` 同基准）。
            # **也收根级文件名写法**（`AGENTS.adoc`、`PUBLIC.adoc`、`README.adoc` 等）：
            # 馆内很自然地会写"登记与维护说明见 `AGENTS.adoc`"，漏收即这类引用悬空
            # 无人发现（实测：把 `AGENTS.adoc` 改成不存在的名字，检查原本不报）。
            # 只认**扩展名在册**的根级文件名（下方白名单），避免把普通词当路径。
            for m in re.findall(r"`((?:(?:specs|library|specs-project-maintainer|script|"
                                r"prompts)/[^`\s]*)|(?:[A-Za-z0-9_.-]+\.(?:adoc|py|txt|md|"
                                r"yml|yaml|json|sh|bat|cmd)))`", line):
                if "/" not in m and m not in _LIB_ROOT_FILES:
                    continue                   # 非根级文件名白名单内 → 当普通词，不核
                if _is_placeholder_ref(m):
                    continue
                _check_library_target(m, f"图书馆内的引用 `{m}`", rel, j)
            # link: 写法：**与反引号同一基准**（见 _lib_resolve）。
            # 馆内 link: 很自然会写根级名（`link:AGENTS_COMMON.adoc[]`、`link:CHANGELOG.adoc[]`），
            # 原实现只按"本文件所在目录"解析 → 同一句引用两种写法结论相反：
            # 文件存在时 link: 形态误报（解析成 library/xxx，不存在）、文件缺失时不报（漏报）。
            for raw in re.findall(r"\blink:([^\[]+)\[", line):
                target = raw.strip()
                if not target or target.startswith("#"):
                    continue
                if re.match(r"^[a-zA-Z][a-zA-Z0-9+.-]*://", target):
                    continue
                if target.startswith("/"):
                    err(f"图书馆内的链接 link:{target}[] 是根绝对路径——"
                        "馆内引用按仓库根基准的相对写法书写，不用根绝对路径", rel, j)
                    continue
                _check_library_target(target, f"图书馆内的链接 link:{target}[]", rel, j,
                                      allow_escape=True)
    phase_done()


def check_library_locating_guard():
    """『依据定位防线』：馆无限大时"怎么准确定位到哪个文件"的协议不得被删或降级。

"""
    phase("依据定位防线检查（馆无限大时的定位协议）")
    if not os.path.isfile(LIBRARY_INDEX):
        err("缺少图书馆入口 library/README.adoc——『依据的定位协议』无处承载"
            "（馆无体量上限时，引用方将退回整馆下载或按文件名猜）", "library/README.adoc")
    else:
        with open(LIBRARY_INDEX, encoding="utf-8") as fh:
            index_text = fh.read()
        miss = [q for q in _LIBRARY_LOCATING_ANCHORS if q not in index_text]
        if miss:
            err(f"图书馆入口缺失『依据定位』要点 {miss}——"
                "馆无限大时定位要么退化成整馆下载/按文件名猜，要么要求取用者先说出 commit"
                "（游客只有 https，取不到）；须写清作者侧/取用侧的区别、入口=常驻层的固定地址、"
                "三步取值、版本固化只是可选加固、且不解析页面结构"
                "（见 library/README.adoc「依据的定位协议」）", "library/README.adoc")

    usage_path = os.path.join(LIBRARY_DIR, "usage.adoc")
    if not os.path.isfile(usage_path):
        err("缺少 library/usage.adoc——『引用方怎么准确定位依据』的使用判据无处承载",
            "library/usage.adoc")
    else:
        with open(usage_path, encoding="utf-8") as fh:
            usage_text = fh.read()
        miss_u = [q for q in _LIBRARY_LOCATING_USAGE_ANCHORS if q not in usage_text]
        if miss_u:
            err(f"library/usage.adoc 缺失『依据定位』使用判据 {miss_u}——"
                "定位协议缺了这条，引用方要么全量下载、要么按路径猜（改名即断档），"
                "要么被要求先取一个它根本取不到的 commit："
                "取用侧只有 https 的前提、主键口径（内容而非路径）、"
                "不承载派生落点的形态约束与终止条件须成文", "library/usage.adoc")

    sources_path = os.path.join(LIBRARY_DIR, "sources.adoc")
    if not os.path.isfile(sources_path):
        err("缺少 library/sources.adoc——定位协议所依赖的机制原文（git / RFC 9110）无处承载",
            "library/sources.adoc")
    else:
        with open(sources_path, encoding="utf-8") as fh:
            sources_text = fh.read()
        miss_s = [q for q in _LIBRARY_LOCATING_SOURCE_MARKERS if q not in sources_text]
        if miss_s:
            err(f"library/sources.adoc 缺失『依据定位』的机制原文/取样状态 {miss_s}——"
                "缺了逐字引文，'主键是内容'与'只取一段'只是本站说法；"
                "缺了'未实测'的标注，会把'支持 Range'当成既定事实"
                "（specs/general/source.adoc「不臆造行为」）", "library/sources.adoc")

    # 『取用前置』回退：把"先取 commit 再拼地址"写回图书馆即命中——游客只有 https
    for rel in (LIBRARY_INDEX, os.path.join(LIBRARY_DIR, "usage.adoc")):
        if not os.path.isfile(rel):
            continue
        with open(rel, encoding="utf-8") as fh:
            text = fh.read()
        for lineno, line in enumerate(text.splitlines(), 1):
            if any(word in line for word in _LOCATING_COMMIT_PREREQ_EXEMPT):
                continue
            for pat, desc in _LOCATING_COMMIT_PREREQ_PATTERNS:
                if pat.search(line):
                    err(f"{rel}:{lineno} 出现『取用前置』回退：{desc}", rel)

    if not os.path.isfile(PROJECT_FILE):
        err("缺少项目规范入口 AGENTS.adoc——图书馆的定位协议无从被读者发现", "AGENTS.adoc")
    else:
        with open(PROJECT_FILE, encoding="utf-8") as fh:
            entry = fh.read()
        if "馆无体量上限" not in entry or "固定地址" not in entry:
            err("项目规范入口未含『依据定位』的口径（馆无体量上限 / 入口 = 常驻层的固定地址）——"
                "读者不知道有这份协议，定位要么重新靠猜、要么退化成"
                "「要求取用侧先取一个它取不到的 commit」（写文件与登记是同一个动作）",
                "AGENTS.adoc")

    # 『文件名』回退：馆内主题文件名过长（把主张写进名字）即命中——名字会被读进每一次链接与
    # 每一次目录列举，且**名字本就不是检索键**（检索键是依据名，经入口主题表解析）。
    lib_dir = os.path.join(REPO_ROOT, "library")
    if os.path.isdir(lib_dir):
        for name in sorted(os.listdir(lib_dir)):
            path = os.path.join(lib_dir, name)
            if not os.path.isfile(path) or not name.endswith(".adoc"):
                continue
            if len(name) > LIBRARY_FILE_NAME_MAX:
                err(f"文件名过长：`library/{name}` 共 {len(name)} 字符，超出上限 "
                    f"{LIBRARY_FILE_NAME_MAX}——图书馆的检索键是**依据名**（经入口「主题登记」表"
                    "解析），**文件名不是主键、也不承担语义**；名字会被读进每一次链接与每一次目录"
                    "列举，长名让每个读者反复白付上下文，且制造『改名即断档』的错觉。请取**单个"
                    "短词、小写 ASCII**，把内容描述写进文件正文"
                    "（见 library/README.adoc「文件名协议（短、无语义、不承担定位）」）",
                    f"library/{name}")
    phase_done()


# 『默认引用面』口径（全仓库统一的表述判据）：**本仓库所有内容都会被发布出去**
# （站点渲染本仓库文档），各内容之间的区别只在"**默认引用什么**"——被引用方按入口加载的
# 是**公共规范**（`AGENTS_COMMON.adoc` + `specs/`），其余落点（图书馆、维护方自查层、
# 站点说明文档等）**不在默认引用面内**（没有公共加载项）。历史口径把后者写成"**本仓库
# 私有 / 不对外发布**"，与平台事实相反：它们同样是被发布的内容（在站点上可读），只是
# 引用方不按入口加载它们、其项目里也没有本仓库的文件。口径写错会连带改错判断：维护方会
# 以为"发布与不发布可选"，而实际只能选择"默认引用面里放什么"。
# 故把**已被纠正的错误表述形态**机械钉住（只认"发布与否"这一形态，不碰"私有落点/
# 私有抓手名"这类**自足性**判据——那拦的是引用好不好用，与发布与否是两件事）。
_REF_SCOPE_BAD_PATTERNS = (
    (re.compile(r"(本仓库|本站)[^。\n]{0,12}私有[^。\n]{0,12}(不随|不分发|不对外|不外发)"),
     "不得写\"本仓库私有…不随规范分发\"——本仓库所有内容都会被发布，应写\"不在默认引用面内\""),
    (re.compile(r"私有内容[^。\n]{0,10}(不随|不对外)"),
     "不得写\"私有内容不随规范分发\"——发布与否不是判据，判据是\"是否被引用方按入口加载\""),
    (re.compile(r"不随规范分发"),
     "不得写\"不随规范分发\"——本仓库全部内容都会被发布，正确表述是\"不在默认引用面内\""),
)
# 豁免：历史记录（`CHANGELOG.adoc` 记录的是**当时口径**，不得改写）；以及**引用/澄清
# 该错误表述本身**的句子（含"不是/并非/≠/不得写/错"等词），以及"私有落点/私有抓手名"
# 这类自足性用语（与发布与否无关）。
_REF_SCOPE_BAD_EXEMPT = ("不是", "并非", "≠", "错误", "不得写", "纠正", "区分")


def check_ref_scope_wording_guard():
    """『默认引用面口径防线』：不得再把本仓库内容写成"私有 / 不对外发布"。

"""
    phase("默认引用面口径检查（不得写成私有/不对外发布）")
    for rel in collect_adoc_files():
        if _is_historical(rel):
            continue                       # 历史条目记的是当时口径，不得改写
        path = os.path.join(REPO_ROOT, *rel.split("/"))
        if not os.path.isfile(path):
            continue
        with open(path, encoding="utf-8") as fh:
            for j, line in enumerate(fh.readlines(), 1):
                if any(w in line for w in _REF_SCOPE_BAD_EXEMPT):
                    continue               # 引用/纠正该表述本身，或讨论"私有落点"这一自足性判据
                for pat, msg in _REF_SCOPE_BAD_PATTERNS:
                    if pat.search(line):
                        err(f"口径错误：{msg}"
                            "（平台事实——本仓库所有内容都会被发布出去，站点可读；"
                            "\"私有\"与事实不符，且会连带把\"发布与否\"误当成可选项）",
                            rel, j)
                        break
    phase_done()


def check_dependency_view_guard():
    """『依赖关系文档防线』：模块间依赖的唯一视图（完整、UML、可直达、不过期）不得被删或降级。

"""
    phase("依赖关系文档防线检查")
    rel = os.path.relpath(DEPENDENCY_VIEW_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(DEPENDENCY_VIEW_FILE):
        err(f"缺少文件 {rel}——『依赖关系文档』的落点丢失"
            "（多模块项目将没有模块间依赖的唯一视图，重复依赖只能靠临场重建依赖树发现）", rel)
        phase_done()
        return
    text = open(DEPENDENCY_VIEW_FILE, encoding="utf-8").read()
    m = re.search(r"^== " + re.escape(DEPENDENCY_VIEW_SECTION) + r".*?(?=^== |\Z)",
                  text, re.S | re.M)
    if m is None:
        err(f"依赖关系文档防线被破坏：{rel} 缺少「{DEPENDENCY_VIEW_SECTION}」节——"
            "模块间依赖的唯一视图（完整依赖关系、UML 表述、先查本文档、缺失即新增）无处承载，"
            "『模块已间接依赖却又加一次』的失效会重新出现", rel)
        section = ""
    else:
        section = m.group(0)
    if section:
        for keys, desc in (
            ((DEPENDENCY_DOC_PATH, "多模块", "文档根目录"),
             "落点与位置：多模块项目须有固定路径 `doc/dependency.adoc`，且写明它放在文档根目录"
             "（使站点导航与 AI 可按固定路径直达）——路径不固定则『先查本文档』无从执行"),
            (("完整", "全部模块", "模块之间"),
             "完整（L1）：须列出**当前项目全部模块之间**的依赖关系，"
             "且写明『完整』的含义是模块之间、而非第三方库清单（否则读者仍要去读构建文件）"),
            (("UML", "依赖箭头"),
             "UML 优先（L1）：依赖关系须以 UML 图为主（模块用组件/包、依赖用依赖箭头），"
             "**不得只写一段文字描述**——文字无法枚举全部模块对"),
            (("先读本视图", "不重启依赖树解析"),
             "先说清『查依赖关系优先查本文档』：涉及依赖判断时先读本视图、回答完即止，"
             "不得每次重新解析依赖树（否则本条等于没写）"),
            (("没有本视图时", "本次任务内", "补全后再用"),
             "文档缺失则新增（L1）：多模块项目没有本视图时须在本次任务内新增/补全，"
             "不得以『存量还没有』为由跳过（否则规则只对已合规的项目生效）"),
            (("同一提交内", "更新本视图"),
             "同提交同步（L1）：模块之间增删依赖、新增/拆分模块后须在同一提交内更新本视图——"
             "视图过期比没有更坏（读者会按它得出错误结论）"),
            (("不得再在它的依赖清单里重复声明", "新增依赖前先读本视图"),
             "不重复声明（L1）：模块已被（直接或间接）依赖时不得重复声明同一依赖，"
             "且须写明新增依赖前先读本视图（这是本条要消灭的那个失效本身）"),
            (("不替代构建工具", "第三方库"),
             "文档与工具各司其职（L2）：本视图不替代构建工具的依赖树"
             "（依赖树只描述第三方库的传递关系、与模块间依赖不是一回事），冲突时以构建文件为准"),
            (("依据", "ISO/IEC/IEEE 42010", "UML"),
             "依据行：须标注标准名/编号（架构描述与 UML 记法、可追溯性、显式声明依赖），"
             "否则后人无从判断它还成不成立"),
        ):
            missing = [k for k in keys if k not in section]
            if missing:
                err(f"依赖关系文档防线被破坏：{rel}「{DEPENDENCY_VIEW_SECTION}」"
                    f"缺失要点 {missing}——{desc}；该条对应用户报告的真实失效"
                    "（模块已间接依赖却又加一次），不得删除、不得降级为建议", rel)
    # 加载调度器：设计文档条目须指向它（多模块项目不知道有这份视图 = 规则不会被触发）
    generic = open(GENERIC_FILE, encoding="utf-8").read()
    if DEPENDENCY_VIEW_SECTION not in generic:
        err("依赖关系文档防线被破坏：AGENTS_COMMON.adoc 的设计文档加载条目未指向"
            f"「{DEPENDENCY_VIEW_SECTION}」——多模块项目与『增删依赖』场景不会加载到它"
            "（规则写了但不会被触发）", "AGENTS_COMMON.adoc")
    # 依赖规范：『引入依赖』须指向本视图（按依赖规范学习时也要能读到）
    dep_file = os.path.join(SPECS_DIR, "general", "dependency.adoc")
    if os.path.isfile(dep_file):
        dtext = open(dep_file, encoding="utf-8").read()
        missing = [k for k in (DEPENDENCY_VIEW_SECTION, "不得重复声明同一依赖",
                               "doc-design.adoc") if k not in dtext]
        if missing:
            err(f"依赖关系文档防线被破坏：specs/general/dependency.adoc 缺失要点 {missing}——"
                "按依赖规范学习时会漏掉『模块间依赖不重复声明、先读依赖视图』这条"
                "（规则被指向，不复制）", "specs/general/dependency.adoc")
    phase_done()


def check_index_page_guard():
    """『索引页触发判据防线』：索引页只对"已承载实质文档"的目录要求，空壳不建、索引只做导航。

"""
    phase("索引页触发判据防线检查")
    if not os.path.isfile(DOC_FILE):
        err("缺少文件 specs/general/doc.adoc——『索引页触发判据』的落点丢失"
            "（「每级目录须有索引页」会被重新读宽成「每个模块都建 doc/README.adoc」）",
            "specs/general/doc.adoc")
        phase_done()
        return
    text = open(DOC_FILE, encoding="utf-8").read()
    if INDEX_PAGE_SECTION not in text:
        err("索引页触发判据防线被破坏：specs/general/doc.adoc 缺少「索引页的触发判据」——"
            "只说「每级目录须有索引页」而不说「该不该建」，AI 会把它读宽成"
            "「每个模块都补一个 doc/README.adoc」并批量生成空壳索引（用户报告的真实失效）",
            "specs/general/doc.adoc")
    else:
        for keys, desc in (
            (("已承载实质文档", "已存在", "实质文档"),
             "触发判据（L1）：索引页只在目录**已承载实质文档**时才需要——"
             "判据是该目录是否已有本级或更深的实质 `.adoc`/`.md`，不得停在「每级目录须有索引页」"),
            (("空目录", "仅有索引页", "不建"),
             "空壳不建（L1）：空目录/仅有索引页「自己」的目录一律不建索引页，"
             "不得为「补索引」先建 `doc/` 目录再放一个 `README.adoc`（这正是批量空壳的成因）"),
            (("只做导航", "不得把上一级文档", "换个壳复制"),
             "索引只做导航（L1）：索引页只指向下级/同级真实文档，"
             "不得把上一级文档（如模块 README）的内容换个壳复制一份——"
             "指向的目标全是别处同一份内容、不含本级自身信息即属空壳，发现即删"),
            (("模块级导航由模块 `README` 承担", "不必", "另设一层索引"),
             "模块级导航归属（L1）：模块总入口本就是模块 `README`，模块内若无独立功能文档，"
             "不必再在 `doc/` 下另设一层索引——否则索引页只是把模块 README 的目录功能复制一份"),
        ):
            missing = [k for k in keys if k not in text]
            if missing:
                err(f"索引页触发判据防线被破坏：specs/general/doc.adoc 缺失要点 {missing}——{desc}；"
                    "该条对应用户报告的真实失效（48 个模块被批量补上同构空壳 `doc/README.adoc`），"
                    "不得删除、不得降级为建议", "specs/general/doc.adoc")
    # 模块级规范：模块 doc 索引条目须同样写明"按需"判据（否则按模块规范学习时会重新读宽）
    if not os.path.isfile(DOC_MODULE_FILE):
        err("缺少文件 specs/general/doc-module.adoc——模块 doc 索引的「按需」判据落点丢失",
            "specs/general/doc-module.adoc")
    else:
        mtext = open(DOC_MODULE_FILE, encoding="utf-8").read()
        missing = [k for k in ("按需", "无任何实质文档", "不建", "模块自身 `README`")
                   if k not in mtext]
        if missing:
            err(f"索引页触发判据防线被破坏：specs/general/doc-module.adoc 缺失要点 {missing}——"
                "模块 `doc/` 索引须写明「按需」（doc/ 下有实质文档才放 README，无则不建、"
                "导航由模块 README 承担），否则「每个模块都该有 doc/README.adoc」会重新成立",
                "specs/general/doc-module.adoc")
    phase_done()


def check_data_dictionary_guard():
    """『数据字典防线（按作用域归档、只引名称、新增与调整即生效）』。

    **本条防的不是"没写规则"，而是"写了规则却仍然膨胀、仍然各写一遍"**——数据字典这类
    规范的典型失效形态是：规则写了，但没人据此把定义归档，于是同一名称在 N 处各带一份定义
    （各自漂移），或"顺手"把只在某文档成立的名称塞进上游落点（字典越滚越大、每次会话都为
    读不到它的项目付上下文）。故本防线按**判据本体**钉住八件事，而不是只核"这一节在不在"：
    ① 引用形态（只引名称、不引定义）；② **作用域分档 + 每档唯一落点**（含**当前文档的定义
    写在该文档开头**——用户点名的那一句）；③ 分档判据可核对；④ **一行一个名称**（每个名称
    独占一段——用户点名"不要挤在一起"）；⑤ 条目形态照 ISO 1087 且
    **定义与使用说明分列**；⑥ 反膨胀的判定标准；⑦ **新增与调整内容时都须判定**（用户原话
    "每次新增、调整内容时都应该生效"）；⑧ 图书馆等"不在默认引用面内"的落点按其自身规则走。
    四处落点须同口径：通用层条文 + 调度器登记 + 文档侧两处互引（`doc.adoc`「文档组织与导航」、
    `encoding.adoc`「术语统一」）——只写条文而不登记，该条永远不会被触发加载（等于没写）。

    判据在 `specs/general/terminology.adoc` 正文里；本函数只核**文本与文件形态**
    （"某个名称到底该归哪一档、某处是否真的复述了定义"属语义判断，交人/子 agent 复核）。
    """
    phase("数据字典防线检查（按作用域归档、只引名称、新增与调整即生效）")
    rel_t = _rel_of(TERMINOLOGY_FILE)
    if not os.path.isfile(TERMINOLOGY_FILE):
        err(f"缺少文件 {rel_t}——『数据字典』的要求无处承载（该节被删后，同一名称又会在各处"
            "各带一份定义、并顺手把下游名称塞进上游落点）", rel_t)
        phase_done()
        return
    ttext = open(TERMINOLOGY_FILE, encoding="utf-8").read()
    if DATA_DICTIONARY_SECTION not in ttext:
        err(f"数据字典防线被破坏：{rel_t} 缺少「{DATA_DICTIONARY_SECTION}」一节——"
            "判据是「只引名称、按作用域归档」这套可核对的规则，不是「要建术语表」这类口号；"
            "整节被删即口径全失", rel_t)
    else:
        for keys, desc in DATA_DICTIONARY_KEYS:
            missing = [k for k in keys if k not in ttext]
            if missing:
                err(f"数据字典防线被破坏：{rel_t} 缺失要点 {missing}——{desc}", rel_t)
        # 作用域分档须**逐档在分档表里**。判定用**表格行的严格形态**
        # （`^|` + 可选强调/代码 `*`\``` + 档位名），不是裸子串：本轮实测，`f"| {scope}"` 这种
        # 子串判定只要正文里出现一处 `| 全局 |` 形态（甚至只是行内代码/表格示例）即**假绿**，
        # 而"档从表里被抽掉、只剩正文一句并列词"正是本条要拦的失效形态。缺一档，该类名称即
        # 无处可归、会被顺手塞进上游落点。
        # 表体取法与本节其它"钉表格行"的防线同一套（本文件既有惯例：`^\|\s*<格内容>` 的
        # 行级正则，格内容允许 1-3 个 `*` 或反引号的强调整体包裹）。
        for scope, desc in DATA_DICTIONARY_SCOPES:
            if not re.search(rf"^\|\s*[*`]{{0,3}}\s*{re.escape(scope)}\s*[*`]{{0,3}}[^|]*\|",
                             ttext, re.M):
                err(f"数据字典防线被破坏：{rel_t} 的作用域分档表缺失「{scope}」档——{desc}；"
                    "每一档都要在分档表里出现并带可核对的落点（尤其是「当前文档」档："
                    "定义写在该文档开头）。判定按**表格行**取值——档位名只出现在正文里"
                    "不算数（正文提到档位名时，『档从表里被抽掉』会假绿）", rel_t)
        # 分档表须是**表**（有落点列与判据列），不是一句并列词——否则"每档唯一落点"无从核对
        if "| 作用域" not in ttext or "唯一落点" not in ttext:
            err(f"数据字典防线被破坏：{rel_t} 的作用域分档不是可核对的表——"
                "须给出「作用域 / 唯一落点 / 判据」三列（只列几个作用域名时，"
                "「每档只一处」与「拿什么判属于哪档」都无从核对）", rel_t)
    # 调度器登记（缺则该条永远不会被触发加载——规则在、但没人会读到）
    rel_g = _rel_of(GENERIC_FILE)
    if not os.path.isfile(GENERIC_FILE):
        err(f"缺少 {rel_g}——调度器登记无从核对", rel_g)
    else:
        gtext = open(GENERIC_FILE, encoding="utf-8").read()
        missing = [k for k in ("terminology.adoc", "新增/调整任何内容时判定名称的落点")
                   if k not in gtext]
        if missing:
            err(f"数据字典防线被破坏：{rel_g} 的通用层未同步该加载项与识别特征 {missing}——"
                "缺则《数据字典》永远不会被触发加载（用户要件「每次新增、调整内容时都应该生效」"
                "在加载这一步就已落空）", rel_g)
    # 文档侧两处互引（改到哪读到哪：读文档规范/编码规范的人须被指到这节）
    for path, keys, desc in (
        (DOC_FILE, ("terminology.adoc", "信息归属"),
         "`specs/general/doc.adoc`「文档组织与导航」须有一行互引，并写明它与「信息归属」的分工"
         "（那条管「一段内容写在哪一层」、本条管「一个名称的定义归在哪一档」）"),
        (ENCODING_FILE, ("terminology.adoc", "数据字典"),
         "`specs/general/encoding.adoc`「术语统一」须有一行互引，写明该条只管「叫法统一」、"
         "定义写在哪儿见《数据字典》"),
    ):
        rel = _rel_of(path)
        if not os.path.isfile(path):
            err(f"缺少文件 {rel}——数据字典缺少该侧互引落点", rel)
            continue
        text = open(path, encoding="utf-8").read()
        miss = [k for k in keys if k not in text]
        if miss:
            err(f"数据字典防线被破坏：{rel} 缺失要点 {miss}——{desc}", rel)
    phase_done()



def check_changelog_entry_guard():
    """『变更日志条目形态防线』：条目须保持**单行**（写法见 `specs/general/changelog.adoc`）。

"""
    phase("变更日志条目形态检查（单行条目）")
    path = os.path.join(REPO_ROOT, "CHANGELOG.adoc")
    if not os.path.isfile(path):
        err("缺少统一变更日志 CHANGELOG.adoc——"
            "变更记录将分散在各文档、多处不一致（见 specs/general/doc-design.adoc"
            "「版本与变更记录」）", "CHANGELOG.adoc")
        phase_done()
        return
    with open(path, encoding="utf-8") as fh:
        lines = fh.read().split("\n")
    for j, line in enumerate(lines, 1):
        if not CHANGELOG_ENTRY_RE.match(line):
            continue
        if len(line) > CHANGELOG_ENTRY_MAX:
            err(f"变更日志条目过长（{len(line)} 字符 > {CHANGELOG_ENTRY_MAX}）——"
                "单行条目须一句话说清'改了什么、给谁带来什么影响'，"
                "超出即说明该拆成多条或删减（specs/general/changelog.adoc「条目书写」）",
                "CHANGELOG.adoc", j)
        nxt = lines[j] if j < len(lines) else ""
        if nxt.strip() and not CHANGELOG_ENTRY_RE.match(nxt) and \
                not nxt.lstrip().startswith("="):
            err("变更日志条目被**续行**（同一条目写成多行）——"
                "条目须单行 `版本号 | 日期 | 变更摘要`、条目内不换行；"
                "被续写的条目会与下一条粘连、渲染成一整段"
                "（specs/general/changelog.adoc「条目书写」）", "CHANGELOG.adoc", j)
    phase_done()


def check_changelog_structure_guard():
    """『变更日志组织形态与表格形态防线』：组织方式、两形态与表格列义不得被删或降级。

"""
    phase("变更日志组织形态与表格形态检查")
    if not os.path.isfile(CHANGELOG_STRUCTURE_FILE):
        err("缺少 specs/general/changelog.adoc——组织形态与表格形态的规则落点消失",
            "specs/general/changelog.adoc")
        phase_done()
        return
    text = open(CHANGELOG_STRUCTURE_FILE, encoding="utf-8").read()
    for keys, desc in CHANGELOG_STRUCTURE_KEYS + CHANGELOG_TABLE_KEYS:
        missing = [k for k in keys if k not in text]
        if missing:
            err(f"变更日志组织形态防线被破坏：specs/general/changelog.adoc 缺失要点 "
                f"{missing}——{desc}", "specs/general/changelog.adoc")
    # 两种条目形态须择一（"不得混用"这句没了，项目会同时维护两套形态）
    if "不得混用" not in text or "流水式" not in text or "表格式" not in text:
        err("变更日志组织形态防线被破坏：specs/general/changelog.adoc 须写明两种条目形态"
            "（流水式 / 表格式）**择一且不得混用**——缺则同一项目会同时维护两套形态",
            "specs/general/changelog.adoc")
    phase_done()

    phase("变更日志形态依据检查（图书馆）")
    if not os.path.isfile(CHANGELOG_EVIDENCE_FILE):
        err("缺少 library/sources.adoc——变更日志形态的依据无处承载",
            "library/sources.adoc")
    else:
        etext = open(CHANGELOG_EVIDENCE_FILE, encoding="utf-8").read()
        for keys, desc in CHANGELOG_EVIDENCE_KEYS:
            missing = [k for k in keys if k not in etext]
            if missing:
                err(f"变更日志形态依据被破坏：library/sources.adoc 缺失要点 {missing}——{desc}",
                    "library/sources.adoc")
    phase_done()


# 『提交信息防线』：提交信息的书写规则（类型前缀、破坏性变更标注）不得被删或降级。
# 背景：本集合早已把 Conventional Commits 1.0.0 的原文收进图书馆（`library/sources.adoc`
# 「变更日志的形态」），但**只用于变更日志的形态**（表格的分组与破坏性变更标注），
# `specs/` 里**没有任何一条约束「提交信息怎么写」**——于是同一条链的「上游」（一次提交改了什么）
# 空着，「下游」（按类型分组）只能靠人工归类。缺口是实打实的（用户要求「取长补短」后补入）。
# 钉住：形态（`<type>[(scope)]: <subject>`）、破坏性变更的两处标注（`!` 与 `BREAKING CHANGE:`
# 页脚）、正文写「为什么」与边界、以及**如实标注这是业界约定而非标准**（Conventional Commits
# 自述 a lightweight convention）与依据落点（图书馆不在引用面内，只留名称/编号）。
COMMIT_MESSAGE_FILE = os.path.join(SPECS_DIR, "general", "git.adoc")
COMMIT_MESSAGE_KEYS = (
    (("== 提交信息",),
     "提交信息的书写规则须有独立承载节（缺则「提交信息怎么写」无处可查，"
     "而变更日志那边却要求按类型分组）"),
    (("<type>[(scope)]: <subject>", "固定闭集"),
     "首行形态须写清：`<type>[(scope)]: <subject>` + 类型取**固定闭集**"
     "（与变更日志的类型同源、不混用同义词）——缺则「有类型前缀」不可核对"),
    (("首行不以", "起头即不合规"),
     "须有**可逐条核对的判定标准**（首行不以 `<type>:` / `<type>(scope):` 起头即不合规）"
     "——只写「建议加类型」无法判定是否被遵守"),
    (("破坏性变更须显式标注", "BREAKING CHANGE", "不得把某个类型默认为破坏性的"),
     "破坏性变更须显式标注：`!` 或 `BREAKING CHANGE:` 页脚，且**不得把某个类型默认为"
     "破坏性的**（破坏性变更可与任何类型组合）——这是与变更日志「不得用类型分级代替"
     "破坏性变更标注」同源的另一半"),
    (("正文写", "为什么"),
     "正文须写「为什么」与影响边界（不重复 diff 已能看出的「改了什么」）"
     "——与变更日志「说影响，不说实现过程」同口径"),
    (("Conventional Commits", "业界约定、非标准"),
     "须**如实标注**依据是业界约定、不是标准（Conventional Commits 自述为"
     "a lightweight convention on top of commit messages）——防被读成"
     "「某标准要求提交信息带类型」"),
)

# 『HTTP 接口语义防线』：方法与状态码的协议语义条文不得被删或降级，且依据须在图书馆。
# 背景：本集合此前只覆盖了 HTTP 接口的**路径命名风格**（`specs/stack/spring.adoc` 中划线），
# **方法与状态码语义未覆盖**——而「GET 承载写操作」「错误一律包 200」是真实项目里最常见的
# 两类语义失效（前者会被爬虫/预取在无人操作时触发副作用，后者让重试、缓存、监控与网关
# 策略全部失效）。补入后须与图书馆依据（RFC 9110 / RFC 9457）对得上，且**级别如实**：
# 安全方法不得产生状态变更是 L1（不可豁免、可判定），幂等/状态码是 L2，Problem Details 是 L3。
HTTP_SEMANTICS_FILE = os.path.join(SPECS_DIR, "general", "coding.adoc")
HTTP_SEMANTICS_KEYS = (
    (("== HTTP 接口语义",),
     "HTTP 接口语义须有独立承载节（缺则方法与状态码语义无处可查，只剩路径命名风格）"),
    (("适用范围", "对外提供或调用 HTTP 接口"),
     "须写明**适用范围**（对外提供或调用 HTTP 接口的项目才适用）——"
     "无 HTTP 接口的项目不应被这条约束（准入面：不引入高频误伤）"),
    (("安全方法不得产生状态变更（L1）", "GET", "HEAD", "OPTIONS", "TRACE"),
     "安全方法不得产生状态变更须是 **L1** 且点明四个安全方法——"
     "这是唯一一条不可豁免且可判定的底线，被降级即等于允许用 GET 做写操作"),
    (("不得", "承载写"),
     "须有正向禁令：不得用安全方法承载写/删/状态流转等有副作用的动作"),
    (("幂等", "PUT", "DELETE", "自动重试"),
     "幂等语义与重试须对齐（`PUT`/`DELETE` 幂等、非幂等请求不得配自动重试）"),
    (("状态码按语义使用（L2）", "4xx", "5xx", "success:false"),
     "状态码按语义使用须是 L2 且含**可判定的反例**（把错误包成 `200` + 响应体 "
     "`success:false`）——没有反例的「按语义使用」无法判定"),
    (("对外错误响应统一结构（L3", "application/problem+json"),
     "Problem Details 须**如实定为 L3（可选）**并点明媒体类型——"
     "外部材料只定义了一种格式、未要求必须采用，不得升成 L1/L2"),
    (("RFC 9110", "RFC 9457"),
     "依据行须写标准名/编号（RFC 9110 / RFC 9457，只写名称、不附链接）"),
)

# 『HTTP 接口语义依据防线』：图书馆侧须有逐字引文与**同义性差异的如实标注**。
# 两处最容易失真的地方：①把「本集合按语义推出的判据化取值」（不得用 200 包错误、
# 非幂等请求不得自动重试）写成标准原文；②把「安全方法不得产生状态变更」与标准的
# 原文要求（资源所有者须在安全方法被访问时禁用该动作）之间的**同义关系**说不清。
HTTP_EVIDENCE_FILE = os.path.join(REPO_ROOT, "library", "sources.adoc")
HTTP_EVIDENCE_KEYS = (
    (("HTTP 接口语义与错误响应（RFC 9110 / RFC 9457）",),
     "图书馆须有该主题节（缺则条文无逐字依据可核对）"),
    (("essentially read-only", "GET, HEAD, OPTIONS, and TRACE methods are defined to be safe"),
     "须有 RFC 9110 安全方法的**逐字**引文锚点（依据不得被压成一句名称）"),
    (("idempotent", "automatically retry"),
     "须有 RFC 9110 幂等与重试的**逐字**引文锚点"),
    (("three-digit integer code",),
     "须有 RFC 9110 状态码定义的**逐字**引文锚点"),
    (("machine-readable details of errors", "application/problem+json"),
     "须有 RFC 9457 的**逐字**引文锚点与媒体类型"),
    (("同义性", "判据化取值"),
     "须**如实标注同义性差异**：标准给的是协议语义，不得用 200 包错误、非幂等请求不得"
     "自动重试是本集合推出的**判据化取值**，不得读成标准原文"),
    (("可选项",),
     "须标明 Problem Details 是标准定义的**格式**、非强制要求（本集合据此定 L3）"),
)


def check_commit_message_guard():
    """『提交信息防线』：提交信息的书写规则不得被删或降级，且依据如实标注。

"""
    phase("提交信息防线检查")
    rel = os.path.relpath(COMMIT_MESSAGE_FILE, REPO_ROOT).replace("\\", "/")
    if not os.path.isfile(COMMIT_MESSAGE_FILE):
        err(f"缺少 {rel}——提交信息的书写规则无处承载（变更日志要求按类型分组，"
            "而提交信息这一上游无任何规则）", rel)
        phase_done()
        return
    text = open(COMMIT_MESSAGE_FILE, encoding="utf-8").read()
    for keys, desc in COMMIT_MESSAGE_KEYS:
        missing = [k for k in keys if k not in text]
        if missing:
            err(f"提交信息防线被破坏：{rel} 缺失要点 {missing}——{desc}", rel)
    phase_done()


